// freigabe blocks outward actions; only the operator can execute them.
// Traps, the secret shield, draft reminders and the read-only log remain.

import { atom, read, update } from 'claude-code'
import type { Elements, EngineInterface, Register, RenderSurface } from 'claude-code'

import type { FreigabeDraft } from '../types'
import {
  KIND_LABEL,
  classifyAllOutward,
  draftIdFrom,
  findTrap,
  hasSecret,
  isOutwardMcp,
  optionValue,
  positionals,
  redactDeep,
  redactText,
  tokenize,
} from './rules'
import type { Outward, SecretHit } from './rules'

const DRAFT_WARN_MS = 20 * 60 * 1000
const DRAFT_FORGET_MS = 24 * 60 * 60 * 1000
const OWN_GITHUB_OWNERS = ['kanevry']
const PROTECTED_BRANCHES = ['main', 'master']

const drafts = atom({ plugin: 'freigabe', key: 'drafts' } as const, [])

type Report = { skip?: boolean }
type LogEntry = { at: number; kind: string; label: string; outcome: string }
type Table = Elements[RenderSurface]
type Ran = { exitCode: number; stdout: string; stderr: string }

// Calls already passed downstream must never run again after a hook failure.
const passed = new Set<string>()

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'freigaben',
      description: 'Freigabe-Protokoll: Entscheidungen, Regel-Fallen, Secrets, offene Mail-Entwürfe',
    })
    const now = await $.clock.now()
    const stored = ((await $.store.get('drafts')) as FreigabeDraft[] | undefined) ?? []
    await update($, drafts, () => stored.filter(d => now - d.at < DRAFT_FORGET_MS))
    // Draft ages change by the minute, and the band shows them.
    $.clock.every(60_000, () => $.ui.invalidate('ui.render'))
    return next(e)
  })

  // ---- Every tool call: guard before, track and shield after -----------------
  on('tool.call', async ($, e, next) => {
    if (passed.has(e.tool_use_id)) return { deny: '[freigabe] Dieser Aufruf wurde bereits weitergereicht und läuft nicht erneut.' }
    const tool = String(e.tool)
    if (e.tool === 'Bash') {
      const refused = await guardShell($, e.command)
      if (refused !== null) return refused
    } else if (isOutwardMcp(tool)) {
      const refused = await guardMcp($, tool)
      if (refused !== null) return refused
    }
    passed.add(e.tool_use_id)
    const ran = await next(e)
    if (ran.deny !== undefined) return ran
    await trackDraft($, tool, e.tool === 'Bash' ? e.command : '', e as unknown as Record<string, unknown>, ran.text ?? '')
    if (ran.text === undefined || !hasSecret(ran.text)) return ran
    const hits: SecretHit[] = []
    if (ran.isError === true) {
      const text = await redactText(ran.text, hits)
      await noteSecrets($, tool, hits)
      return { deny: `[freigabe] Fehlerausgabe enthielt ein Secret und ist geschwärzt:\n${text}` }
    }
    const result = (await redactDeep(ran.result, hits)) as typeof ran.result
    await noteSecrets($, tool, hits)
    return { result, context: [secretNote(hits)] }
  }).catch(($, e) => {
    if (passed.has(e.tool_use_id)) {
      return { deny: '[freigabe] Die Ausgabe ließ sich nicht auf Secrets prüfen (Fehler im Schutz-Hook) und wird zurückgehalten. Den Operator fragen.' }
    }
    return { deny: '[freigabe] Schutz-Hook fehlgeschlagen; der Aufruf läuft nicht. Den Operator fragen.' }
  })

  // ---- /freigaben ------------------------------------------------------------
  on('command.run', { command: 'freigaben' }, async $ => {
    const log = ((await $.store.get('log')) as LogEntry[] | undefined) ?? []
    const open = await read($, drafts)
    const now = await $.clock.now()
    const out: string[] = []
    out.push(log.length === 0 ? 'Noch nichts protokolliert.' : `Protokoll, letzte ${Math.min(15, log.length)} von ${log.length}:`)
    for (const entry of log.slice(-15)) {
      out.push(`  ${clock(entry.at)}  ${entry.kind.padEnd(22)} ${entry.outcome.padEnd(26)} ${entry.label.slice(0, 90)}`)
    }
    out.push('')
    out.push(open.length === 0 ? 'Keine offenen Mail-Entwürfe.' : 'Offene Mail-Entwürfe:')
    for (const d of open) out.push(`  Entwurf ${d.id}  seit ${Math.round((now - d.at) / 60_000)} min  ${d.label}`)
    return { text: out.join('\n') }
  })

  // ---- Drawing -----------------------------------------------------------------
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const t = $.ui.resolve(e)
    const now = await $.clock.now()
    const stale = (await read($, drafts)).filter(d => now - d.at > DRAFT_WARN_MS)
    const below = await next(e)
    if (stale.length === 0) return below
    const { Box } = t
    const mine = drawDrafts(t, stale, now, () => void dismissDrafts($))
    return below ? (
      <Box flexDirection="column">
        {mine}
        {below}
      </Box>
    ) : (
      mine
    )
  })
}

// ---- Guards -------------------------------------------------------------------

type Refusal = { deny: string }

/** A refusal for a shell command, or null to let it run. Traps first, then actions with an effect outside. */
async function guardShell($: EngineInterface, command: string): Promise<Refusal | null> {
  const trap = findTrap(command)
  if (trap !== null) {
    $.ui.toast(`Regel-Falle abgefangen: ${trap.title}`, { timeoutMs: 8000 })
    await remember($, { kind: 'Regel-Falle', label: trap.title, outcome: 'abgefangen' })
    return { deny: `[freigabe · Regel-Falle ${trap.id}] ${trap.why}\nStattdessen: ${trap.fix}` }
  }
  // Jeder Treffer zaehlt: nur wenn alle Treffer der Zeile skippen, laeuft sie (review R1).
  for (const hit of classifyAllOutward(command)) {
    const report = await measure($, hit)
    if (report.skip !== true) return refuseOutward($, KIND_LABEL[hit.kind], command)
  }
  return null
}

/** Refuses outward MCP calls without executing them. */
async function guardMcp($: EngineInterface, tool: string): Promise<Refusal> {
  return refuseOutward($, KIND_LABEL.mcp, tool)
}

async function refuseOutward($: EngineInterface, kind: string, command: string): Promise<Refusal> {
  // Geschwaerzt, bevor der Befehl in Protokoll ($.store) oder deny-Text gelangt (review R1).
  const label = oneLine(await redactText(command, []))
  await remember($, { kind, label, outcome: 'abgelehnt' })
  return { deny: `[freigabe] Nicht ausgeführt: Aktion mit Außenwirkung (${kind}: ${label}). freigabe gibt nichts frei; der Operator führt sie selbst aus oder entlädt den Mod.` }
}

/** Remembers a draft that apple-mail draft/reply or the MCP draft tools opened in Mail.app. */
async function trackDraft($: EngineInterface, tool: string, command: string, input: Record<string, unknown>, text: string): Promise<void> {
  const viaShell = /\bapple-mail\s+(draft|reply)\b/.test(command)
  const viaMcp = /^mcp__apple-mail__mail_(reply_)?draft$/.test(tool)
  if (!viaShell && !viaMcp) return
  const id = draftIdFrom(text)
  if (id === undefined) return
  const words = tokenize(command)
  const subject = viaMcp ? String(input.subject ?? '') : (optionValue(words, '--subject') ?? '')
  const to = viaMcp ? String(input.to ?? '') : (optionValue(words, '--to') ?? '')
  const label = subject !== '' ? `„${subject.slice(0, 50)}“` : to !== '' ? `an ${to}` : `Antwort, Entwurf ${id}`
  const now = await $.clock.now()
  const list = [...(await read($, drafts)).filter(d => d.id !== id), { id, at: now, label }]
  await update($, drafts, () => list)
  await $.store.set('drafts', list)
}

// ---- Measure only the exceptions that may skip blocking -----------------------

const PUSH_VALUED = new Set(['-o', '--push-option', '--receive-pack', '--exec', '--repo'])

async function measure($: EngineInterface, hit: Outward): Promise<Report> {
  if (hit.kind !== 'push' && hit.kind !== 'external-gh') return {}
  try {
    const cwd = await resolveCwd($, hit.dir)
    if (cwd === null) return {}
    return hit.kind === 'push' ? await measurePush($, hit, cwd) : await measureGithub($, hit, cwd)
  } catch {
    return {}
  }
}

async function measurePush($: EngineInterface, hit: Outward, cwd: string): Promise<Report> {
  const args = hit.args
  const pos = positionals(args, PUSH_VALUED)
  const isForce =
    args.some(a => a === '--force' || a.startsWith('--force-with-lease') || a === '--force-if-includes' || /^-[a-zA-Z]*f[a-zA-Z]*$/.test(a)) ||
    pos.slice(1).some(p => p.startsWith('+'))
  const withTags = args.some(a => a === '--tags' || a === '--follow-tags' || a === '--mirror' || a === '--all')
  const isDelete = args.includes('--delete') || args.includes('-d') || pos.slice(1).some(p => p.startsWith(':'))
  const currentRead = await run($, ['git', 'rev-parse', '--abbrev-ref', 'HEAD'], cwd)
  const upstreamRead = await run($, ['git', 'rev-parse', '--abbrev-ref', '@{u}'], cwd)
  const current = currentRead.stdout.trim()
  const upstream = upstreamRead.stdout.trim()
  const specs = pos.slice(1)
  if (specs.length === 0 && (currentRead.exitCode !== 0 || current === '' || current === 'HEAD' || upstreamRead.exitCode !== 0 || upstream === '')) return {}
  const remote = pos[0] ?? optionValue(args, '--repo') ?? ((await run($, ['git', 'config', `branch.${current}.remote`], cwd)).stdout.trim() || 'origin')
  const urlRead = await run($, ['git', 'remote', 'get-url', remote], cwd)
  if (urlRead.exitCode !== 0 || urlRead.stdout.trim() === '') return {}

  const pairs =
    specs.length === 0
      ? [{ src: 'HEAD', dst: upstream.startsWith(`${remote}/`) ? upstream.slice(remote.length + 1) : current }]
      : specs.map(spec => {
          const bare = spec.replace(/^\+/, '')
          const [src, dst] = bare.includes(':') ? bare.split(':') : [bare, bare]
          const target = (dst ?? '').replace(/^refs\/heads\//, '')
          return { src: src === '' || src === undefined ? 'HEAD' : src, dst: target === '' || target === 'HEAD' ? current : target }
        })
  if (pairs.some(pair => pair.dst === '' || pair.dst === 'HEAD' || pair.dst.includes('*') || pair.dst.startsWith('refs/tags/'))) return {}
  if (pairs.some(pair => pair.dst === current) && (currentRead.exitCode !== 0 || current === '')) return {}
  let isTagSpec = false
  for (const pair of pairs) {
    if ((await run($, ['git', 'rev-parse', '--verify', '--quiet', `refs/tags/${pair.dst}`], cwd)).exitCode === 0) isTagSpec = true
  }
  const hitsProtected = pairs.some(pair => PROTECTED_BRANCHES.includes(pair.dst))
  // `git switch main && git push`: the branch checked out now is not the one pushed.
  const isUnsure = hit.switchedBefore === true && specs.length === 0
  if (!isForce && !withTags && !isDelete && !hitsProtected && !isTagSpec && !isUnsure) {
    return { skip: true }
  }

  return {}
}

async function measureGithub($: EngineInterface, hit: Outward, cwd: string): Promise<Report> {
  let repo = optionValue(hit.args, '-R', '--repo')
  if (repo === undefined) {
    const shown = await run($, ['gh', 'repo', 'view', '--json', 'nameWithOwner', '-q', '.nameWithOwner'], cwd, 15_000)
    repo = shown.exitCode === 0 ? shown.stdout.trim() : undefined
  }
  const owner = repo?.split('/')[0]?.toLowerCase()
  if (owner !== undefined && OWN_GITHUB_OWNERS.includes(owner)) return { skip: true }
  return {}
}

// ---- Helpers that reach the host -------------------------------------------------

async function run($: EngineInterface, argv: string[], cwd: string, timeoutMs = 10_000): Promise<Ran> {
  try {
    return await $.process.run(argv, { cwd, timeoutMs })
  } catch (error) {
    return { exitCode: -1, stdout: '', stderr: String(error) }
  }
}

// Resolves a `cd` target to an absolute folder, or null if it doesn't exist.
// The target is passed as an argument, never as source.
const CD_SCRIPT = `unset CDPATH; d="$1"; case "$d" in "~") d="$HOME";; "~/"*) d="$HOME/\${d#\\~/}";; esac; cd -- "$d" 2>/dev/null && pwd -P`

async function resolveCwd($: EngineInterface, dir: string | null): Promise<string | null> {
  const sessionCwd = await $.session.cwd()
  if (dir === null) return sessionCwd
  const ran = await run($, ['bash', '-c', CD_SCRIPT, 'freigabe', dir], sessionCwd, 5000)
  const out = ran.stdout.trim()
  return ran.exitCode === 0 && out !== '' ? out : null
}

async function remember($: EngineInterface, entry: Omit<LogEntry, 'at'>): Promise<void> {
  const at = await $.clock.now()
  const log = ((await $.store.get('log')) as LogEntry[] | undefined) ?? []
  await $.store.set('log', [...log, { ...entry, at }].slice(-100))
}

async function dismissDrafts($: EngineInterface): Promise<void> {
  const list = await read($, drafts)
  await update($, drafts, () => [])
  await $.store.set('drafts', [])
  await remember($, { kind: 'Mail-Entwurf', label: list.map(d => d.label).join(', '), outcome: 'als erledigt markiert' })
}

async function noteSecrets($: EngineInterface, tool: string, hits: SecretHit[]): Promise<void> {
  const names = [...new Set(hits.map(hit => hit.name))].join(', ')
  $.ui.toast(`Secret in der Ausgabe von ${tool}: ${names}. Geschwärzt, trotzdem rotieren (SEC-008).`, { timeoutMs: 15_000 })
  for (const hit of hits) {
    await remember($, { kind: 'Secret im Output', label: `${hit.name} sha256:${hit.fp} (${tool})`, outcome: 'geschwärzt, rotieren' })
  }
}

function secretNote(hits: SecretHit[]): string {
  const names = [...new Set(hits.map(hit => hit.name))].join(', ')
  return `[freigabe] Die Ausgabe enthielt ${hits.length} Secret(s) (${names}). Sie sind für dich und im Transkript durch Platzhalter ersetzt. Der Wert wurde trotzdem ausgegeben: den Operator auf Rotation hinweisen (SEC-008), den Wert nicht erneut ausgeben und keine Edits mit dem Platzhalter bauen.`
}

// ---- Drawing -----------------------------------------------------------------------

function oneLine(command: string): string {
  return command.replace(/\s+/g, ' ').trim().slice(0, 300)
}

function clock(ms: number): string {
  const d = new Date(ms)
  const pad = (n: number) => String(n).padStart(2, '0')
  return `${pad(d.getDate())}.${pad(d.getMonth() + 1)}. ${pad(d.getHours())}:${pad(d.getMinutes())}`
}

function drawDrafts(t: Table, stale: readonly FreigabeDraft[], now: number, onDone: () => void) {
  const { Box, Text, Button } = t
  const oldest = stale.reduce((a, b) => (a.at <= b.at ? a : b))
  const minutes = Math.round((now - oldest.at) / 60_000)
  const what = stale.length === 1 ? 'Ein Mail-Entwurf' : `${stale.length} Mail-Entwürfe`
  return (
    <Box flexDirection="column">
      <Box gap={2}>
        <Text color="yellow" wrap="truncate-end">
          ✉ {what} offen, ältester seit {minutes} min: {oldest.label}
        </Text>
        <Button key="drafts-done" label="Erledigt" hotkey="e" plain onPress={onDone} />
      </Box>
      <Text dimColor wrap="truncate-end">
        Ein offenes Verfassen-Fenster ist einen Tastendruck vom Versand entfernt (G2): schließen oder selbst versenden.
      </Text>
    </Box>
  )
}

