// The pure half of the freigabe mod: reading a shell command and a tool's
// output. Nothing here touches `$`, so every rule is testable on its own.

// ---- Reading a shell command ------------------------------------------------

/** Splits one segment into words, honouring quotes. Good enough to read flags and paths. */
export function tokenize(text: string): string[] {
  const words: string[] = []
  const re = /"((?:[^"\\]|\\.)*)"|'([^']*)'|(\S+)/g
  let m: RegExpExecArray | null
  while ((m = re.exec(text)) !== null) {
    words.push(m[1] ?? m[2] ?? m[3] ?? '')
  }
  return words
}

// Words that can come before the real command without changing what it does.
const PREFIXES = new Set(['command', 'exec', 'nohup', 'time', 'then', 'do', 'else', '!', 'sudo'])

/** The words of one segment, leading `VAR=x`, `env -u X` and the prefixes above removed. */
export function commandWords(segment: string): string[] {
  const words = tokenize(segment.trim().replace(/^[({]+\s*/, '').replace(/\s*[)}]+$/, ''))
  for (;;) {
    const word = words[0]
    if (word === undefined) break
    if (/^[A-Za-z_][A-Za-z0-9_]*=/.test(word) || PREFIXES.has(word)) {
      words.shift()
      continue
    }
    if (word === 'env') {
      words.shift()
      while (words[0]?.startsWith('-')) {
        const option = words.shift()
        if (option === '-u') words.shift()
      }
      continue
    }
    break
  }
  // npx vercel, pnpm dlx vercel, pnpm exec changeset: the tool is the next word.
  if (words[0] === 'npx' || words[0] === 'bunx') words.shift()
  if (words[0] === 'pnpm' && (words[1] === 'dlx' || words[1] === 'exec')) words.splice(0, 2)
  return words
}

/** The command line cut at `&&`, `||`, `;`, `|` and newlines. Quotes are not honoured: detection only. */
export function splitSegments(command: string): string[] {
  return command.split(/&&|\|\||;|\||\n/)
}

/** The pipelines of a command line, each a list of its stages. */
export function splitPipelines(command: string): string[][] {
  return command.split(/&&|\|\||;|\n/).map(pipeline => pipeline.split('|'))
}

function baseName(word: string): string {
  return word.replace(/^\\/, '').split('/').pop() ?? word
}

/** A folder a later `cd arg` moves to, given the folder so far (null = the session folder). */
function joinDir(dir: string | null, arg: string | undefined): string {
  if (arg === undefined || arg === '~' || arg.startsWith('/') || arg.startsWith('~/')) {
    return arg ?? '~'
  }
  return dir ? `${dir}/${arg}` : arg
}

/** The positional arguments, skipping each option and, for the options in `valued`, its value. */
export function positionals(args: readonly string[], valued: ReadonlySet<string>): string[] {
  const out: string[] = []
  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i] ?? ''
    if (arg === '--') {
      out.push(...args.slice(i + 1))
      break
    }
    if (arg.startsWith('-') && arg !== '-') {
      if (valued.has(arg)) i += 1
      continue
    }
    out.push(arg)
  }
  return out
}

/** The value of `--name value`, `--name=value` or `-n value`, or undefined. */
export function optionValue(args: readonly string[], ...names: string[]): string | undefined {
  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i] ?? ''
    for (const name of names) {
      if (arg === name) return args[i + 1]
      if (arg.startsWith(`${name}=`)) return arg.slice(name.length + 1)
    }
  }
  return undefined
}

// ---- Actions with an effect outside this machine -----------------------------

export type OutwardKind =
  | 'mail-send'
  | 'merge'
  | 'push'
  | 'publish'
  | 'deploy'
  | 'release'
  | 'external-gh'
  | 'mcp'

export const KIND_LABEL: Record<OutwardKind, string> = {
  'mail-send': 'Mail versenden',
  merge: 'Merge',
  push: 'Push',
  publish: 'Paket veröffentlichen',
  deploy: 'Produktiv-Deploy',
  release: 'Release',
  'external-gh': 'Beitrag in fremdem GitHub-Repo',
  mcp: 'MCP-Aktion mit Außenwirkung',
}

export type Outward = {
  kind: OutwardKind
  /** The detected action. */
  label: string
  /** The command's own words after the subcommand. */
  args: string[]
  /** Where a `cd` earlier on the line moved to; null means the session folder. */
  dir: string | null
  /** For merges and releases: which forge CLI. */
  forge?: 'glab' | 'gh'
  /** For deploys: which tool. */
  tool?: string
  /** For pushes: an earlier segment switched branches, so the branch now checked out is not the one pushed. */
  switchedBefore?: boolean
}

/** The first segment of a shell command that acts outside this machine, or null. */
/** The first action with an effect outside, or null (tests and labels). */
export function classifyOutward(command: string): Outward | null {
  return classifyAllOutward(command)[0] ?? null
}

/**
 * Every action with an effect outside, one per segment: `git push origin feat && git push origin main`
 * holds two, and a skippable first one must not let the second run (review R1, gate-host).
 */
export function classifyAllOutward(command: string): Outward[] {
  const hits: Outward[] = []
  let dir: string | null = null
  let switched = false
  for (const segment of splitSegments(command)) {
    const words = commandWords(segment)
    const [first, ...args] = words
    if (first === undefined) continue
    const cmd = baseName(first)
    if (cmd === 'cd' || cmd === 'pushd') {
      dir = joinDir(dir, args[0])
      continue
    }
    const hit = classifyWords(cmd, args, dir)
    if (hit !== null) hits.push(hit.kind === 'push' && switched ? { ...hit, switchedBefore: true } : hit)
    if (cmd === 'git' && args.some(a => a === 'switch' || a === 'checkout')) switched = true
  }
  return hits
}

function classifyWords(cmd: string, args: string[], dir: string | null): Outward | null {
  const [sub, action] = args
  if (cmd === 'apple-mail' && sub === 'send') {
    return { kind: 'mail-send', label: 'apple-mail send', args: args.slice(1), dir }
  }
  if (cmd === 'git') {
    let gitDir = dir
    let i = 0
    while (i < args.length && (args[i] ?? '').startsWith('-')) {
      if (args[i] === '-C' && i + 1 < args.length) {
        gitDir = joinDir(gitDir, args[i + 1])
        i += 2
      } else if (args[i] === '-c' && i + 1 < args.length) {
        i += 2
      } else {
        i += 1
      }
    }
    if (args[i] === 'push') {
      const rest = args.slice(i + 1)
      if (rest.includes('--dry-run') || rest.includes('-n')) return null
      return { kind: 'push', label: 'git push', args: rest, dir: gitDir }
    }
    return null
  }
  // Wrapper wie glab-<name> sprechen dieselbe API wie glab; ohne Host im Mod (Grenze bleibt CLI-Tor).
  if (cmd === 'glab' || cmd === 'gh' || /^glab-[a-z0-9-]+$/.test(cmd)) {
    const forge = cmd === 'gh' ? 'gh' : 'glab'
    if ((sub === 'mr' || sub === 'pr') && action === 'merge') {
      return { kind: 'merge', label: `${cmd} ${sub} merge`, args: args.slice(2), dir, forge }
    }
    if (sub === 'release' && action === 'create') {
      return { kind: 'release', label: `${cmd} release create`, args: args.slice(2), dir, forge }
    }
    if (
      cmd === 'gh' &&
      (sub === 'pr' || sub === 'issue') &&
      ['create', 'comment', 'review', 'edit', 'close', 'reopen'].includes(action ?? '')
    ) {
      return { kind: 'external-gh', label: `gh ${sub} ${action}`, args: args.slice(2), dir, forge }
    }
    return null
  }
  const joined = [cmd, ...args].join(' ')
  if (args.includes('--dry-run')) return null
  if (
    /^(npm|pnpm|yarn) (-r |--recursive )?publish\b/.test(joined) ||
    /^yarn npm publish\b/.test(joined) ||
    /^(changeset|pnpm changeset) publish\b/.test(joined) ||
    /^cargo publish\b/.test(joined)
  ) {
    return { kind: 'publish', label: joined.split(' ').slice(0, 3).join(' '), args, dir, tool: cmd }
  }
  if (cmd === 'vercel' && (args.includes('--prod') || args.includes('--production') || sub === 'promote' || sub === 'rollback')) {
    return { kind: 'deploy', label: `vercel ${args.filter(a => !a.startsWith('--token')).join(' ')}`.trim(), args, dir, tool: 'vercel' }
  }
  if (cmd === 'supabase' && ((sub === 'db' && (action === 'push' || (action === 'reset' && args.includes('--linked')))) || (sub === 'migration' && action === 'up' && args.includes('--linked')))) {
    return { kind: 'deploy', label: `supabase ${sub} ${action}`, args, dir, tool: 'supabase' }
  }
  if ((cmd === 'fly' || cmd === 'flyctl') && sub === 'deploy') {
    return { kind: 'deploy', label: 'fly deploy', args, dir, tool: 'fly' }
  }
  if (cmd === 'railway' && sub === 'up') {
    return { kind: 'deploy', label: 'railway up', args, dir, tool: 'railway' }
  }
  return null
}

// Reads never wait, even when their name carries a write verb (`get_purchase_quote`).
const MCP_READS = /^(API-)?(get|list|search|query|retrieve|read|count|aggregate|view|find|filter)[-_]/i
const MCP_WRITES = /(^|[-_])(buy|purchase|delete|trash|share|send|publish|promote|rollback|transfer|pause|cancel|revoke|respond)([-_]|$)|^(create_deployment|calendar_add|add_project_domain|update_firewall_config|put_firewall_config|create_project_env|edit_project_env|update_shared_env_variable|issue_cert|upload_cert|join_team|accept_project_transfer_request)$/i

/** Whether an MCP tool's name says it buys, deletes, shares, sends, publishes or deploys. */
export function isOutwardMcp(tool: string): boolean {
  if (!tool.startsWith('mcp__')) return false
  const name = tool.split('__').pop() ?? ''
  return !MCP_READS.test(name) && MCP_WRITES.test(name)
}

// ---- Traps the rules name ---------------------------------------------------

export type Trap = { id: string; title: string; why: string; fix: string }

const SECRET_VAR = /\$\{?([A-Z][A-Z0-9_]*(?:TOKEN|SECRET|PASSWORD|PASSWD|API_KEY|_KEY|_PAT))\b/
const ENV_FILE = /(^|\/)\.env(\.(?!example\b|sample\b|template\b|schema\b)[\w.-]+)?$/
const KEYS_ONLY = /cut\s+-d\s*['"]?=['"]?\s+-f\s*1|sed\s+['"]?s\/=\.\*\/\/|awk\s+-F\s*['"]?=['"]?\s+['"]?\{\s*print\s+\$1/

/** The first trap the rules of this estate name in a shell command, or null. */
export function findTrap(command: string): Trap | null {
  for (const segment of splitSegments(command)) {
    const words = commandWords(segment)
    const [first, ...args] = words
    if (first === undefined) continue
    const cmd = baseName(first)

    if (
      cmd === 'claude' &&
      args.some(a => a === '-p' || a === '--print') &&
      !/env\s+(-\S+\s+)*-u\s+ANTHROPIC_API_KEY\b|unset\s+ANTHROPIC_API_KEY\b/.test(command)
    ) {
      return {
        id: 'claude-p-oauth',
        title: 'claude -p ohne env -u ANTHROPIC_API_KEY',
        why: 'claude -p erbt sonst den ANTHROPIC_API_KEY aus älteren Shells und rechnet über die bezahlte API ab statt über OAuth (Memory "claude -p nur über OAuth").',
        fix: `env -u ANTHROPIC_API_KEY ${segment.trim()}`,
      }
    }

    if (['cat', 'less', 'more', 'head', 'tail', 'bat', 'nl', 'strings'].includes(cmd) && args.some(a => ENV_FILE.test(a))) {
      const file = args.find(a => ENV_FILE.test(a)) ?? '.env'
      return {
        id: 'sec008-env-datei',
        title: `${cmd} ${file}`,
        why: 'Gibt Secret-Werte in Transkript und Log aus (SEC-008: never emit, do not mask).',
        fix: `sed -n 's/^\\([A-Z_][A-Z0-9_]*\\)=.*/\\1/p' ${file}   # nur die Schlüssel`,
      }
    }

    if (cmd === 'docker' && (args[0] === 'inspect' || (args[0] === 'container' && args[1] === 'inspect'))) {
      const formatted = args.some(a => a === '-f' || a === '--format' || a.startsWith('--format=') || /^-f./.test(a))
      if (!formatted) {
        return {
          id: 'sec008-docker-inspect',
          title: 'docker inspect ohne --format',
          why: 'docker inspect druckt Config.Env im Klartext (SEC-008).',
          fix: "docker exec <container> printenv | cut -d= -f1 | sort   # oder: docker inspect -f '{{.State.Status}}' <container>",
        }
      }
    }

    if (cmd === 'git' && args[0] === 'add' && args.slice(1).some(a => a === '.' || a === '-A' || a === '--all' || a === ':/')) {
      return {
        id: 'commit-discipline-add',
        title: 'git add . / -A / --all',
        why: 'Pauschales Stagen nimmt die Arbeit paralleler Sessions mit (commit-discipline, PSA-004).',
        fix: 'git add <datei> <datei> …   # einzeln nach Namen, dann git diff --cached prüfen',
      }
    }

    if (cmd === 'curl') {
      if (/-H\s*["']?Authorization:\s*(Bearer|token)\s+\$|--header\s*["']?Authorization:\s*(Bearer|token)\s+\$/i.test(segment)) {
        return {
          id: 'sec008-secret-argv',
          title: 'Token in curl-Argumenten',
          why: 'Argumente sind für jeden lokalen User in ps lesbar und landen in Shell-History und Logs (SEC-008).',
          fix: `printf 'header = "Authorization: Bearer %s"' "$TOKEN" | curl --config - <url>`,
        }
      }
      if (/[?&](access_token|private_token|api_key|apikey|token|key)=\$/i.test(segment)) {
        return {
          id: 'sec008-token-in-url',
          title: 'Token in der URL',
          why: 'Query-Strings landen in Server-, Proxy- und Referer-Logs (SEC-008).',
          fix: 'Token als Header über curl --config - übergeben, nie in der URL.',
        }
      }
    }
  }

  if (/\$\{?PIPESTATUS\[/.test(command)) {
    return {
      id: 'zsh-pipestatus',
      title: '${PIPESTATUS[0]} in zsh',
      why: 'Die Shell hier ist zsh: ${PIPESTATUS[0]} ist leer, und ein leeres EXIT= liest sich wie Erfolg (bash-harness-pitfalls §6).',
      fix: 'cmd > /tmp/out.log 2>&1; rc=$?; tail -5 /tmp/out.log; echo "EXIT=$rc"',
    }
  }

  if (/\bgrep\s+(?:-[A-Za-z]*c[A-Za-z]*|--count)\b[^\n]*?\|\|\s*echo\s+["']?0["']?/.test(command)) {
    return {
      id: 'grep-c-echo-0',
      title: 'grep -c … || echo 0',
      why: 'grep -c druckt bei keinem Treffer selbst 0 und endet mit 1: das Ergebnis ist "0\\n0" und bricht jeden Zahlenvergleich (bash-harness-pitfalls §1).',
      fix: 'count=$(grep -c "MUSTER" datei || true)',
    }
  }

  for (const stages of splitPipelines(command)) {
    // tokenize, not commandWords: a bare `env` is the command here, not a prefix.
    const head = tokenize((stages[0] ?? '').trim())
    const rest = stages.slice(1).join('|')
    const headCmd = baseName(head[0] ?? '')
    const dumpsEnv =
      ((headCmd === 'env' || headCmd === 'printenv') && head.length === 1) ||
      (headCmd === 'export' && head[1] === '-p' && head.length === 2) ||
      (headCmd === 'printenv' && head.length === 2 && SECRET_VAR.test(`$${head[1] ?? ''}`))
    if (dumpsEnv && !KEYS_ONLY.test(rest)) {
      return {
        id: 'sec008-env-dump',
        title: `${head.join(' ')} ohne Filter`,
        why: 'Ein Umgebungs-Dump druckt jeden Token-Wert ins Transkript (SEC-008).',
        fix: 'env | cut -d= -f1 | sort   # Schlüssel; Einzelwert: test -n "${VAR:-}" && echo "VAR: set"',
      }
    }
    const last = stages[stages.length - 1] ?? ''
    const lastCmd = baseName(commandWords(last)[0] ?? '')
    if ((lastCmd === 'echo' || lastCmd === 'printf') && SECRET_VAR.test(last)) {
      const name = last.match(SECRET_VAR)?.[1] ?? 'VAR'
      return {
        id: 'sec008-echo-secret',
        title: `echo $${name}`,
        why: 'Druckt den Wert ins Transkript (SEC-008). Prüfen geht ohne Ausgabe.',
        fix: `test -n "\${${name}:-}" && echo "${name}: set"; echo "\${#${name}}"   # gesetzt? Länge?`,
      }
    }
  }
  return null
}

// ---- Secrets in output ------------------------------------------------------

export type SecretHit = { name: string; fp: string }

export const SECRET_PATTERNS: readonly { name: string; re: RegExp }[] = [
  { name: 'Private Key', re: /-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g },
  { name: 'GitLab-Token', re: /\bgl(?:pat|dt|rt|ptt|cbt|soat|ffct|imt|oas|agent)-[A-Za-z0-9_-]{20,}/g },
  { name: 'GitHub-Token', re: /\b(?:gh[pousr]_[A-Za-z0-9]{36,}|github_pat_[A-Za-z0-9_]{22,})/g },
  { name: 'Anthropic-Key', re: /\bsk-ant-[A-Za-z0-9_-]{20,}/g },
  { name: 'OpenAI-Key', re: /\bsk-(?:proj-|svcacct-)?(?!ant-)[A-Za-z0-9_-]{32,}/g },
  { name: 'Stripe-Key', re: /\b(?:sk|rk)_(?:live|test)_[A-Za-z0-9]{20,}/g },
  { name: 'Stripe-Webhook-Secret', re: /\bwhsec_[A-Za-z0-9]{24,}/g },
  { name: 'AWS-Access-Key', re: /\b(?:AKIA|ASIA)[0-9A-Z]{16}\b/g },
  { name: 'Slack-Token', re: /\bxox[abprs]-[A-Za-z0-9-]{10,}/g },
  { name: 'Google-API-Key', re: /\bAIza[0-9A-Za-z_-]{35}\b/g },
]

export function hasSecret(text: string): boolean {
  return SECRET_PATTERNS.some(({ re }) => (text.match(re)?.length ?? 0) > 0)
}

async function fingerprint(secret: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(secret))
  return [...new Uint8Array(digest)].map(b => b.toString(16).padStart(2, '0')).join('').slice(0, 12)
}

/** The text with every secret replaced by its kind and a sha256 fingerprint. */
export async function redactText(text: string, hits: SecretHit[]): Promise<string> {
  let out = text
  for (const { name, re } of SECRET_PATTERNS) {
    for (const secret of new Set(out.match(re) ?? [])) {
      const fp = await fingerprint(secret)
      if (!hits.some(hit => hit.fp === fp)) hits.push({ name, fp })
      out = out.split(secret).join(`[${name} entfernt · sha256:${fp}]`)
    }
  }
  return out
}

/** A copy of any JSON-like value with every string redacted. */
export async function redactDeep(value: unknown, hits: SecretHit[]): Promise<unknown> {
  if (typeof value === 'string') {
    return hasSecret(value) ? redactText(value, hits) : value
  }
  if (Array.isArray(value)) {
    const out: unknown[] = []
    for (const item of value) out.push(await redactDeep(item, hits))
    return out
  }
  if (value !== null && typeof value === 'object') {
    const out: Record<string, unknown> = {}
    for (const [key, item] of Object.entries(value)) out[key] = await redactDeep(item, hits)
    return out
  }
  return value
}

// ---- Mail drafts ------------------------------------------------------------

/** The draft id that `apple-mail draft|reply` or the MCP draft tools printed, or undefined. */
export function draftIdFrom(text: string): string | undefined {
  return text.match(/draft id:\s*(\d+)/i)?.[1] ?? text.match(/"draftId"\s*:\s*"?(\d+)/)?.[1]
}

